const Contact = () => {
    return (
        <section>
            <h1>Contact</h1>
            <p>Email: [Your Email]</p>
            <p>
                <a href="[Your GitHub Link]" target="_blank" rel="noopener noreferrer">GitHub</a>
            </p>
            <p>
                <a href="[Your LinkedIn Link]" target="_blank" rel="noopener noreferrer">LinkedIn</a>
            </p>
        </section>
    );
};

export default Contact;
